import { CommandHandler, ICommandHandler, EventBus } from '@nestjs/cqrs';

export class CreateUserCommand {
  constructor(public readonly email: string, public readonly name: string) {}
}

@CommandHandler(CreateUserCommand)
export class CreateUserHandler implements ICommandHandler<CreateUserCommand> {
  constructor(private repository: UserRepository, private eventBus: EventBus) {}

  async execute(command: CreateUserCommand) {
    const user = await this.repository.create({ email: command.email, name: command.name });

    // ✅ Publish event: Sagas or event handlers handle emails/analytics independently!
    this.eventBus.publish(new UserCreatedEvent(user.id));
    return user;
  }
}
